        LocalDate date = ((java.sql.Date) o.get("delivery_date")).toLocalDate();
        if ("Confirmed".equals(toStatus)) {
            for (Map<String, Object> r : aggregatedItems(orderId)) {
                long dishId = ((Number) r.get("dish_id")).longValue();
