1	package com.webox.auth;
2	
3	import com.webox.common.Api;
4	import com.webox.common.RateLimiter;
5	import com.webox.common.Util;
6	import com.webox.dto.Dtos;
7	import com.webox.security.JwtService;
8	import com.webox.security.UserPrincipal;
9	import org.springframework.dao.DuplicateKeyException;
10	import org.springframework.jdbc.core.JdbcTemplate;
11	import org.springframework.security.crypto.password.PasswordEncoder;
12	import org.springframework.stereotype.Service;
13	import org.springframework.transaction.annotation.Transactional;
14	
15	import java.security.SecureRandom;
16	import java.time.LocalDateTime;
17	import java.util.Base64;
18	import java.util.LinkedHashMap;
19	import java.util.Map;
20	
21	@Service
22	public class AuthService {
23	    private final JdbcTemplate jdbc;
24	    private final PasswordEncoder encoder;
25	    private final JwtService jwt;
26	    private final RateLimiter limiter;
27	    private final SecureRandom random = new SecureRandom();
28	
29	    public AuthService(JdbcTemplate jdbc, PasswordEncoder encoder, JwtService jwt, RateLimiter limiter) {
30	        this.jdbc = jdbc;
31	        this.encoder = encoder;
32	        this.jwt = jwt;
33	        this.limiter = limiter;
34	    }
35	
36	    @Transactional
37	    public Map<String, Object> register(Dtos.RegisterReq req) {
38	        String email = req.email().trim().toLowerCase();
39	        if (email.length() > 200) throw Api.error(400, "VALIDATION_EMAIL_LENGTH", "Email is too long");
40	        checkPassword(req.password());
41	        String displayName = req.displayName() == null ? null : req.displayName().trim();
42	        if (displayName != null && displayName.length() > 100) {
43	            throw Api.error(400, "VALIDATION_INVALID", "displayName must be at most 100 characters");
44	        }
45	        try {
46	            jdbc.update("INSERT INTO users(email,password_hash,display_name,role) VALUES (?,?,?,'EMPLOYEE')",
47	                    email, encoder.encode(req.password()), displayName);
48	        } catch (DuplicateKeyException e) {
49	            throw Api.error(409, "AUTH_EMAIL_EXISTS", "Email already registered");
50	        }
51	        Long id = jdbc.queryForObject("SELECT id FROM users WHERE email=?", Long.class, email);
52	        Map<String, Object> user = new LinkedHashMap<>();
53	        user.put("id", id);
54	        user.put("email", email);
55	        user.put("role", "EMPLOYEE");
56	        return user;
57	    }
58	
59	    public Map<String, Object> login(Dtos.LoginReq req, String ip) {
60	        String email = req.email().trim().toLowerCase();
61	        limiter.check("login:ip:" + ip, 20, 60_000);
62	        limiter.check("login:ipmail:" + ip + ":" + email, 10, 60_000);
63	        Map<String, Object> row;
64	        try {
65	            row = jdbc.queryForMap("SELECT id,email,password_hash,role,status FROM users WHERE email=?", email);
66	        } catch (Exception e) {
67	            throw Api.error(401, "AUTH_INVALID_CREDENTIALS", "Invalid email or password");
68	        }
69	        if (!"ACTIVE".equals(row.get("status")) || !encoder.matches(req.password(), String.valueOf(row.get("password_hash")))) {
70	            throw Api.error(401, "AUTH_INVALID_CREDENTIALS", "Invalid email or password");
71	        }
72	        long id = ((Number) row.get("id")).longValue();
73	        String role = String.valueOf(row.get("role"));
74	        String access = jwt.issue(new UserPrincipal(id, email, role));
75	        String refresh = issueRefresh(id);
76	        Map<String, Object> user = new LinkedHashMap<>();
77	        user.put("id", id);
78	        user.put("email", email);
79	        user.put("role", role);
80	        Map<String, Object> data = new LinkedHashMap<>();
81	        data.put("accessToken", access);
82	        data.put("refreshToken", refresh);
83	        data.put("expiresIn", jwt.accessTtlSeconds());
84	        data.put("user", user);
85	        return data;
86	    }
87	
88	    @Transactional
89	    public Map<String, Object> refresh(Dtos.RefreshReq req) {
90	        String hash = Util.sha256(req.refreshToken());
91	        Map<String, Object> row;
92	        try {
93	            row = jdbc.queryForMap("SELECT id,user_id,revoked,expires_at FROM refresh_tokens WHERE token_hash=?", hash);
94	        } catch (Exception e) {
95	            throw Api.error(401, "AUTH_TOKEN_INVALID", "Invalid refresh token");
96	        }
97	        if (Util.intVal(row.get("revoked")) != 0
98	                || ((java.sql.Timestamp) row.get("expires_at")).toLocalDateTime().isBefore(LocalDateTime.now())) {
99	            throw Api.error(401, "AUTH_TOKEN_INVALID", "Invalid refresh token");
100	        }
101	        long tokenId = ((Number) row.get("id")).longValue();
102	        long userId = ((Number) row.get("user_id")).longValue();
103	        int revoked = jdbc.update("UPDATE refresh_tokens SET revoked=1 WHERE id=? AND revoked=0", tokenId);
104	        if (revoked == 0) throw Api.error(401, "AUTH_TOKEN_INVALID", "Invalid refresh token");
105	        Map<String, Object> user = jdbc.queryForMap("SELECT id,email,role FROM users WHERE id=?", userId);
106	        String access = jwt.issue(new UserPrincipal(userId, String.valueOf(user.get("email")), String.valueOf(user.get("role"))));
107	        String refresh = issueRefresh(userId);
108	        Map<String, Object> u = new LinkedHashMap<>();
109	        u.put("id", userId);
110	        u.put("email", user.get("email"));
111	        u.put("role", user.get("role"));
112	        Map<String, Object> data = new LinkedHashMap<>();
113	        data.put("accessToken", access);
114	        data.put("refreshToken", refresh);
115	        data.put("expiresIn", jwt.accessTtlSeconds());
116	        data.put("user", u);
117	        return data;
118	    }
119	
120	    public Map<String, Object> logout(Dtos.RefreshReq req) {
121	        jdbc.update("UPDATE refresh_tokens SET revoked=1 WHERE token_hash=?", Util.sha256(req.refreshToken()));
122	        return new LinkedHashMap<>();
123	    }
124	
125	    public Map<String, Object> me(long userId) {
126	        Map<String, Object> row = jdbc.queryForMap("SELECT id,email,role,display_name FROM users WHERE id=?", userId);
127	        Map<String, Object> data = new LinkedHashMap<>();
128	        data.put("id", row.get("id"));
129	        data.put("email", row.get("email"));
130	        data.put("role", row.get("role"));
131	        data.put("displayName", row.get("display_name"));
132	        return data;
133	    }
134	
135	    private String issueRefresh(long userId) {
136	        byte[] raw = new byte[32];
137	        random.nextBytes(raw);
138	        String token = Base64.getUrlEncoder().withoutPadding().encodeToString(raw);
139	        jdbc.update("INSERT INTO refresh_tokens(user_id,token_hash,expires_at) VALUES (?,?,?)",
140	                userId, Util.sha256(token), LocalDateTime.now().plusDays(7));
141	        return token;
142	    }
143	
144	    private void checkPassword(String p) {
145	        if (p == null || p.length() < 8 || p.length() > 64
146	                || !p.chars().anyMatch(Character::isLetter) || !p.chars().anyMatch(Character::isDigit)) {
147	            throw Api.error(400, "VALIDATION_PASSWORD_POLICY",
148	                    "Password must be 8-64 characters and contain both letters and digits");
149	        }
150	    }
151	}

