28	    @GetMapping("/preferences")
29	    public Map<String, Object> getPreferences() {
30	        long uid = SecurityConfig.current().id();
31	        List<Map<String, Object>> rows = jdbc.queryForList("SELECT * FROM user_preferences WHERE user_id=?", uid);
32	        Map<String, Object> data = new LinkedHashMap<>();
33	        if (rows.isEmpty()) {
34	            data.put("allergens", List.of());
35	            data.put("preferredCategories", List.of());
36	            data.put("spicePreference", null);
37	            data.put("tastePreference", null);
38	            data.put("budgetMinCents", null);
39	            data.put("budgetMaxCents", null);
40	            data.put("recommendEnabled", false);
41	            return Api.ok(data);
42	        }
43	        Map<String, Object> r = rows.get(0);
44	        data.put("allergens", Util.parseList((String) r.get("allergens")));
45	        data.put("preferredCategories", Util.parseList((String) r.get("preferred_categories")));
46	        data.put("spicePreference", r.get("spice_preference"));
47	        data.put("tastePreference", r.get("taste_preference"));
48	        data.put("budgetMinCents", r.get("budget_min_cents"));
49	        data.put("budgetMaxCents", r.get("budget_max_cents"));
50	        data.put("recommendEnabled", Util.intVal(r.get("recommend_enabled")) == 1);
51	        return Api.ok(data);
52	    }
