54	    @PutMapping("/preferences")
55	    public Map<String, Object> putPreferences(@RequestBody Dtos.PrefReq req) {
56	        long uid = SecurityConfig.current().id();
57	        List<String> allergens = req.allergens() == null ? List.of() : req.allergens();
58	        List<String> categories = req.preferredCategories() == null ? List.of() : req.preferredCategories();
59	        for (String a : allergens) {
60	            if (!Util.ALLERGENS.contains(a)) throw Api.error(400, "VALIDATION_CATEGORY", "Invalid allergen: " + a);
61	        }
62	        for (String c : categories) {
63	            if (!Util.CATEGORIES.contains(c)) throw Api.error(400, "VALIDATION_CATEGORY", "Invalid category: " + c);
64	        }
65	        if (req.spicePreference() != null && !Util.SPICE.contains(req.spicePreference())) {
66	            throw Api.error(400, "VALIDATION_CATEGORY", "Invalid spice preference");
67	        }
68	        if (req.tastePreference() != null && !List.of("Light", "Medium", "Rich").contains(req.tastePreference())) {
69	            throw Api.error(400, "VALIDATION_CATEGORY", "Invalid taste preference");
70	        }
71	        if (req.budgetMinCents() != null && req.budgetMaxCents() != null
72	                && (req.budgetMinCents() <= 0 || req.budgetMinCents() > req.budgetMaxCents())) {
73	            throw Api.error(400, "VALIDATION_INVALID", "Budget requires 0 < min <= max");
74	        }
75	        jdbc.update("INSERT INTO user_preferences(user_id,allergens,preferred_categories,spice_preference,taste_preference,"
76	                        + "budget_min_cents,budget_max_cents,recommend_enabled) VALUES (?,?,?,?,?,?,?,?) "
77	                        + "ON DUPLICATE KEY UPDATE allergens=VALUES(allergens), preferred_categories=VALUES(preferred_categories),"
78	                        + " spice_preference=VALUES(spice_preference), taste_preference=VALUES(taste_preference),"
79	                        + " budget_min_cents=VALUES(budget_min_cents), budget_max_cents=VALUES(budget_max_cents),"
80	                        + " recommend_enabled=VALUES(recommend_enabled)",
81	                uid, Util.json(allergens), Util.json(categories), req.spicePreference(), req.tastePreference(),
82	                req.budgetMinCents(), req.budgetMaxCents(), Boolean.TRUE.equals(req.recommendEnabled()) ? 1 : 0);
83	        return getPreferences();
84	    }
