88	        long uid = SecurityConfig.current().id();
89	        List<Map<String, Object>> rows = jdbc.queryForList(
90	                "SELECT id,address,last_used_at FROM addresses WHERE user_id=? ORDER BY last_used_at DESC, id DESC", uid);
91	        List<Map<String, Object>> out = new ArrayList<>();
