102	    @PostMapping("/addresses")
103	    public ResponseEntity<Map<String, Object>> addAddress(@Valid @RequestBody Dtos.AddressReq req) {
104	        long uid = SecurityConfig.current().id();
105	        String address = req.address().trim();
106	        if (address.isEmpty()) throw Api.error(400, "VALIDATION_ADDRESS_LENGTH", "Address is required");
107	        try {
108	            jdbc.update("INSERT INTO addresses(user_id,address) VALUES (?,?)", uid, address);
109	        } catch (DuplicateKeyException ignored) {
110	            // unique (user_id,address): return existing
111	        }
112	        Long id = jdbc.queryForObject("SELECT id FROM addresses WHERE user_id=? AND address=?", Long.class, uid, address);
113	        Map<String, Object> data = new LinkedHashMap<>();
114	        data.put("id", id);
115	        data.put("address", address);
116	        return ResponseEntity.status(HttpStatus.CREATED).body(Api.ok(data));
117	    }
