119	    @DeleteMapping("/addresses/{id}")
120	    public Map<String, Object> deleteAddress(@PathVariable long id) {
121	        long uid = SecurityConfig.current().id();
122	        int n = jdbc.update("DELETE FROM addresses WHERE id=? AND user_id=?", id, uid);
123	        if (n == 0) throw Api.error(404, "NOT_FOUND", "Address not found");
124	        Map<String, Object> data = new LinkedHashMap<>();
125	        data.put("deleted", true);
126	        return Api.ok(data);
127	    }
128	}

